  + MaxCapacity : int
}

class Person {
  + FirstName : string
  + FamilyName : string
  + BirthDate : date
}

class Trainer {
  + Diploma : string
}

class Member {
}

class Prospect {
}

class Intern {
}

class Session {
  + Date : date
  + StartHour : time
}

class IndividualSession {
}

class GroupSession {
  + Type : string
}

Center "1" *-- "1..*" Room
Room "1" -- "0..*" Session
Person --|> Trainer
Person --|> Member
Person --|> Prospect
Trainer --|> Intern

Trainer "1" -- "0..*" Session : supervises
Person "0..*" -- "0..*" Session : participates

GroupSession --|> Session
IndividualSession --|> Session

Trainer "1" -- "1" GroupSession : leads
@enduml

